//! Round-trip and fixture tests for the Arrow IPC reader/writer.
//!
//! Two directions are pinned here:
//!
//! - **our writer → our reader**: every engine type, NULLs in every column,
//!   several chunks including an empty table, batch boundaries at
//!   `CHUNK_SIZE`, NaN/±inf, unicode and empty strings, error cases;
//! - **pyarrow → our reader**: the committed fixtures under `tests/fixtures`
//!   (generated by pyarrow 26.0.0 — see `generate_fixtures.py`) pin the
//!   foreign-writer direction: widening legs (`Int8`/`UInt32`/`Float32`/
//!   `LargeUtf8`/`Date64`), every timestamp unit, decimal, the three interval
//!   layouts, compressed files, the stream refusal, and unsupported types.
//!
//! The pyarrow → *our* direction cannot run in CI without Python; the wave's
//! verification ran it once with the venv script documented next to the
//! fixtures and the report records the outcome.

use std::path::{Path, PathBuf};
use std::sync::Arc;

use pinkdb::filefmt::FileFormat;
use pinkdb::types::Interval;
use pinkdb::vector::{CHUNK_SIZE, Vector, VectorData};
use pinkdb::{DataTable, DataType, Value};
use pinkdb_arrow::{ArrowFormat, EXTENSION_NAME};

/// A unique scratch path per test (tests run in parallel).
fn scratch(name: &str) -> PathBuf {
    let mut p = std::env::temp_dir();
    p.push(format!(
        "pinkdb-arrow-test-{}-{}-{name}",
        std::process::id(),
        std::time::SystemTime::now()
            .duration_since(std::time::UNIX_EPOCH)
            .unwrap()
            .as_nanos()
    ));
    p
}

fn fixtures(name: &str) -> PathBuf {
    Path::new(env!("CARGO_MANIFEST_DIR"))
        .join("tests")
        .join("fixtures")
        .join(name)
}

fn vec_of(dtype: DataType, values: &[Value]) -> Vector {
    let mut v = Vector::with_capacity(dtype, values.len());
    for value in values {
        v.push_value(value.clone()).unwrap();
    }
    v
}

/// A table covering every engine type, with NULLs, split into explicit chunk
/// sizes (two chunks here: 3 + 2 rows).
fn all_types_table(name: &str) -> DataTable {
    let schema = vec![
        ("b".to_string(), DataType::Boolean),
        ("i".to_string(), DataType::Integer),
        ("bi".to_string(), DataType::Bigint),
        ("d".to_string(), DataType::Double),
        ("s".to_string(), DataType::Varchar),
        ("dt".to_string(), DataType::Date),
        ("ts".to_string(), DataType::Timestamp),
        (
            "dec".to_string(),
            DataType::Decimal {
                precision: 18,
                scale: 4,
            },
        ),
        ("iv".to_string(), DataType::Interval),
    ];
    let mut t = DataTable::new(name.to_string(), schema).unwrap();
    t.append_chunk(vec![
        vec_of(
            DataType::Boolean,
            &[Value::Boolean(true), Value::Null, Value::Boolean(false)],
        ),
        vec_of(
            DataType::Integer,
            &[Value::Integer(1), Value::Null, Value::Integer(-3)],
        ),
        vec_of(
            DataType::Bigint,
            &[Value::Bigint(2), Value::Null, Value::Bigint(-(2i64 << 52))],
        ),
        vec_of(
            DataType::Double,
            &[
                Value::Double(1.5),
                Value::Null,
                Value::Double(f64::INFINITY),
            ],
        ),
        vec_of(
            DataType::Varchar,
            &[
                Value::Varchar("héllo".to_string()),
                Value::Null,
                Value::Varchar(String::new()),
            ],
        ),
        vec_of(
            DataType::Date,
            &[Value::Date(0), Value::Null, Value::Date(19723)],
        ),
        vec_of(
            DataType::Timestamp,
            &[
                Value::Timestamp(1),
                Value::Null,
                Value::Timestamp(-1_700_000_000_000_001),
            ],
        ),
        vec_of(
            DataType::Decimal {
                precision: 18,
                scale: 4,
            },
            &[Value::Decimal(12345, 4), Value::Null, Value::Decimal(-1, 4)],
        ),
        vec_of(
            DataType::Interval,
            &[
                Value::Interval {
                    months: 1,
                    days: 2,
                    micros: 3,
                },
                Value::Null,
                Value::Interval {
                    months: -1,
                    days: -2,
                    micros: -1_500,
                },
            ],
        ),
    ])
    .unwrap();
    t.append_chunk(vec![
        vec_of(DataType::Boolean, &[Value::Null, Value::Boolean(true)]),
        vec_of(DataType::Integer, &[Value::Integer(4), Value::Integer(-4)]),
        vec_of(DataType::Bigint, &[Value::Bigint(8), Value::Bigint(-8)]),
        vec_of(
            DataType::Double,
            &[Value::Double(f64::NAN), Value::Double(-0.0)],
        ),
        vec_of(
            DataType::Varchar,
            &[
                Value::Varchar("b2a".to_string()),
                Value::Varchar("b2b".to_string()),
            ],
        ),
        vec_of(DataType::Date, &[Value::Date(1), Value::Date(2)]),
        vec_of(
            DataType::Timestamp,
            &[Value::Timestamp(10), Value::Timestamp(20)],
        ),
        vec_of(
            DataType::Decimal {
                precision: 18,
                scale: 4,
            },
            &[Value::Decimal(20_000, 4), Value::Decimal(35_000, 4)],
        ),
        vec_of(
            DataType::Interval,
            &[
                Value::Interval {
                    months: 0,
                    days: 1,
                    micros: 2,
                },
                Value::Interval {
                    months: 2,
                    days: 0,
                    micros: 0,
                },
            ],
        ),
    ])
    .unwrap();
    t
}

/// Compare two tables cell by cell (NaN- and -0.0-aware for DOUBLE).
fn assert_tables_equal(got: &DataTable, want: &DataTable) {
    assert_eq!(got.schema(), want.schema(), "schema");
    assert_eq!(got.num_rows, want.num_rows, "row count");
    for row in 0..want.num_rows {
        for col in 0..want.num_cols() {
            let (g, w) = (
                got.get(row, col).expect("cell"),
                want.get(row, col).expect("cell"),
            );
            match (g, w) {
                (Value::Double(a), Value::Double(b)) => {
                    assert_eq!(a.to_bits(), b.to_bits(), "double at ({row},{col})")
                }
                (a, b) => assert_eq!(a, b, "cell at ({row},{col})"),
            }
        }
    }
}

#[test]
fn roundtrip_all_supported_types_nulls_and_chunks() {
    let table = all_types_table("t");
    let path = scratch("all-types.arrow");
    let format = ArrowFormat::new();
    format.write(&path, &table).expect("write");

    // The schema-only read agrees with the full read.
    assert_eq!(format.schema(&path).unwrap(), table.schema());

    let back = format.read(&path).expect("read");
    assert_tables_equal(&back, &table);
    // 5 rows land in one engine chunk on read (< CHUNK_SIZE).
    assert_eq!(back.num_chunks(), 1);
    std::fs::remove_file(&path).ok();
}

#[test]
fn empty_table_roundtrips() {
    let table = DataTable::new(
        "empty".to_string(),
        vec![
            ("a".to_string(), DataType::Integer),
            ("s".to_string(), DataType::Varchar),
        ],
    )
    .unwrap();
    assert_eq!(table.num_rows, 0);
    let path = scratch("empty.arrow");
    let format = ArrowFormat::new();
    format.write(&path, &table).expect("write");
    let back = format.read(&path).expect("read");
    assert_eq!(back.schema(), table.schema());
    assert_eq!(back.num_rows, 0);
    assert_eq!(format.schema(&path).unwrap(), table.schema());
    std::fs::remove_file(&path).ok();
}

#[test]
fn writer_emits_one_batch_per_engine_chunk() {
    use arrow_ipc::reader::FileReader;
    let rows = CHUNK_SIZE * 2 + 7;
    let values: Vec<Value> = (0..rows as i32).map(Value::Integer).collect();
    let mut table = DataTable::new(
        "big".to_string(),
        vec![("id".to_string(), DataType::Integer)],
    )
    .unwrap();
    // Three chunks: 2048 + 2048 + 7.
    table
        .append_chunk(vec![vec_of(DataType::Integer, &values[..CHUNK_SIZE])])
        .unwrap();
    table
        .append_chunk(vec![vec_of(
            DataType::Integer,
            &values[CHUNK_SIZE..2 * CHUNK_SIZE],
        )])
        .unwrap();
    table
        .append_chunk(vec![vec_of(DataType::Integer, &values[2 * CHUNK_SIZE..])])
        .unwrap();

    let path = scratch("batches.arrow");
    ArrowFormat::new().write(&path, &table).unwrap();
    let reader = FileReader::try_new_buffered(std::fs::File::open(&path).unwrap(), None).unwrap();
    assert_eq!(reader.num_batches(), 3);
    let back = ArrowFormat::new().read(&path).unwrap();
    assert_eq!(back.num_rows, rows);
    assert_eq!(back.num_chunks(), 3);
    assert_tables_equal(&back, &table);
    std::fs::remove_file(&path).ok();
}

#[test]
fn nulls_in_every_column_survive() {
    let table = all_types_table("n");
    let path = scratch("nulls.arrow");
    let format = ArrowFormat::new();
    format.write(&path, &table).unwrap();
    let back = format.read(&path).unwrap();
    // Row 1 is all-NULL in every column.
    for col in 0..back.num_cols() {
        assert_eq!(back.get(1, col), Some(Value::Null), "column {col}");
    }
    std::fs::remove_file(&path).ok();
}

#[test]
fn missing_file_and_non_arrow_files_are_clean_errors() {
    let format = ArrowFormat::new();
    let missing = scratch("missing.arrow");
    let err = format.read(&missing).unwrap_err().to_string();
    assert!(err.contains("cannot open"), "{err}");

    let text = scratch("not-arrow.arrow");
    std::fs::write(&text, b"hello, this is not arrow").unwrap();
    let err = format.schema(&text).unwrap_err().to_string();
    assert!(err.contains("not an Arrow IPC file"), "{err}");
    std::fs::remove_file(&text).ok();
}

#[test]
fn reads_pyarrow_golden_types() {
    let path = fixtures("golden_types.arrow");
    let format = ArrowFormat::new();
    let schema = format.schema(&path).expect("schema");
    // The widening legs are pinned by the engine schema itself.
    let dtypes: Vec<(&str, DataType)> = schema.iter().map(|(n, t)| (n.as_str(), *t)).collect();
    assert_eq!(
        dtypes,
        vec![
            ("b", DataType::Boolean),
            ("i8", DataType::Integer),
            ("i16", DataType::Integer),
            ("i32", DataType::Integer),
            ("i64", DataType::Bigint),
            ("u8", DataType::Integer),
            ("u16", DataType::Integer),
            ("u32", DataType::Bigint),
            ("f16", DataType::Double),
            ("f32", DataType::Double),
            ("f64", DataType::Double),
            ("s", DataType::Varchar),
            ("ls", DataType::Varchar),
            ("d32", DataType::Date),
            ("d64", DataType::Date),
            ("ts_s", DataType::Timestamp),
            ("ts_ms", DataType::Timestamp),
            ("ts_us", DataType::Timestamp),
            ("ts_ns", DataType::Timestamp),
            (
                "dec",
                DataType::Decimal {
                    precision: 18,
                    scale: 4
                }
            ),
            ("iv", DataType::Interval),
        ]
    );
    let t = format.read(&path).expect("read");
    assert_eq!(t.num_rows, 5);
    let col = |name: &str| t.columns[t.column_index(name).unwrap()].dtype;
    assert_eq!(col("i8"), DataType::Integer);

    let get = |row: usize, name: &str| t.get(row, t.column_index(name).unwrap()).expect("cell");
    // Batch 1, row 0/2 and batch 2 (rows 3..5) — NULLs at row 1.
    assert_eq!(get(0, "b"), Value::Boolean(true));
    assert_eq!(get(1, "b"), Value::Null);
    assert_eq!(get(2, "i8"), Value::Integer(127));
    assert_eq!(get(3, "i8"), Value::Integer(1));
    assert_eq!(get(0, "u32"), Value::Bigint(4_294_967_295));
    assert_eq!(get(2, "f16"), Value::Double(-0.25));
    assert_eq!(get(0, "f32"), Value::Double(1.25));
    assert_eq!(get(1, "f64"), Value::Null);
    assert_eq!(get(2, "f64"), Value::Double(f64::INFINITY));
    assert_eq!(get(0, "s"), Value::Varchar("héllo".to_string()));
    assert_eq!(get(2, "s"), Value::Varchar(String::new()));
    assert_eq!(get(0, "ls"), Value::Varchar("large-1".to_string()));
    assert_eq!(get(2, "d32"), Value::Date(19723));
    assert_eq!(get(3, "d64"), Value::Date(1));
    // Timestamp seconds/milliseconds scale to micros; nanoseconds truncate.
    assert_eq!(get(2, "ts_s"), Value::Timestamp(1_700_000_000_000_000));
    assert_eq!(get(2, "ts_ms"), Value::Timestamp(1_700_000_000_123_000));
    assert_eq!(get(0, "ts_us"), Value::Timestamp(1));
    // -1000 ns truncates toward zero to -1 µs.
    assert_eq!(get(2, "ts_ns"), Value::Timestamp(-1));
    assert_eq!(get(0, "dec"), Value::Decimal(12345, 4));
    assert_eq!(get(2, "dec"), Value::Decimal(-1, 4));
    assert_eq!(
        get(0, "iv"),
        Value::Interval {
            months: 1,
            days: 2,
            micros: 3
        }
    );
    assert_eq!(get(1, "iv"), Value::Null);
    // -1500 ns truncates toward zero to -1 µs.
    assert_eq!(
        get(2, "iv"),
        Value::Interval {
            months: -1,
            days: -2,
            micros: -1
        }
    );
}

#[test]
fn reads_multi_batch_files_and_rechunks_at_chunk_size() {
    let t = ArrowFormat::new()
        .read(&fixtures("golden_bulk.arrow"))
        .expect("read");
    assert_eq!(t.num_rows, 2050);
    // Two source batches (1234 + 816) re-chunk into 2048 + 2.
    assert_eq!(t.num_chunks(), 2);
    assert_eq!(t.columns[0].chunks[0].len(), CHUNK_SIZE);
    assert_eq!(t.columns[0].chunks[1].len(), 2);
    assert_eq!(t.get(0, 0), Some(Value::Integer(0)));
    assert_eq!(t.get(2047, 0), Some(Value::Integer(2047)));
    assert_eq!(t.get(2048, 0), Some(Value::Integer(2048)));
    assert_eq!(t.get(2049, 1), Some(Value::Varchar("t5".to_string())));
}

#[test]
fn reads_compressed_ipc_files() {
    for file in ["golden_lz4.arrow", "golden_zstd.arrow"] {
        let t = ArrowFormat::new()
            .read(&fixtures(file))
            .unwrap_or_else(|e| panic!("{file}: {e}"));
        assert_eq!(t.num_rows, 3, "{file}");
        assert_eq!(t.get(0, 0), Some(Value::Integer(1)), "{file}");
        // Same payload in both files — the compression wrapper is the only
        // difference.
        for (row, text) in [(0, "lz4"), (1, "zstd"), (2, "none")] {
            assert_eq!(
                t.get(row, 1),
                Some(Value::Varchar(text.to_string())),
                "{file} row {row}"
            );
        }
    }
}

#[test]
fn stream_files_are_refused_with_the_format_difference() {
    let err = ArrowFormat::new()
        .read(&fixtures("golden_stream.arrows"))
        .unwrap_err()
        .to_string();
    assert!(err.contains("Arrow IPC stream"), "{err}");
    assert!(err.contains("ARROW1"), "{err}");
}

#[test]
fn unsupported_columns_are_refused_at_schema_time() {
    let err = ArrowFormat::new()
        .schema(&fixtures("golden_unsupported.arrow"))
        .unwrap_err()
        .to_string();
    assert!(err.contains("blob"), "{err}");
    assert!(err.contains("Binary"), "{err}");
    // The refusal happens before any row is produced; the reader never
    // half-decodes a file.
    let err = ArrowFormat::new()
        .read(&fixtures("golden_unsupported.arrow"))
        .unwrap_err()
        .to_string();
    assert!(err.contains("cannot be read exactly"), "{err}");
}

/// The registered name/extension/function surface the engine resolves
/// through (kept here so the constants and the trait impl cannot drift).
#[test]
fn format_identity_is_stable() {
    let f = ArrowFormat::new();
    assert_eq!(f.name(), EXTENSION_NAME);
    assert_eq!(f.name(), "arrow");
    assert!(f.extensions().contains(&"feather"));
    assert!(f.read_functions().contains(&"read_arrow"));
    // `Debug` is required by the engine registry.
    let _ = format!("{:?}", Arc::new(f));
}

/// A hand-built vector with an explicit validity mask: the writer must
/// preserve exactly the valid/invalid pattern.
#[test]
fn explicit_validity_masks_survive_the_roundtrip() {
    let words = vec![0b1011u64];
    let v = Vector::from_raw(VectorData::Int32(vec![7, 9, 11, 13]), words);
    let mut t = DataTable::new(
        "mask".to_string(),
        vec![("v".to_string(), DataType::Integer)],
    )
    .unwrap();
    t.append_chunk(vec![v]).unwrap();
    let path = scratch("mask.arrow");
    let f = ArrowFormat::new();
    f.write(&path, &t).unwrap();
    let back = f.read(&path).unwrap();
    // 0b1011: rows 0, 1 and 3 valid, row 2 NULL.
    assert_eq!(back.get(0, 0), Some(Value::Integer(7)));
    assert_eq!(back.get(1, 0), Some(Value::Integer(9)));
    assert_eq!(back.get(2, 0), Some(Value::Null));
    assert_eq!(back.get(3, 0), Some(Value::Integer(13)));
    std::fs::remove_file(&path).ok();
}

/// Interval values beyond Arrow's nanosecond range are refused instead of
/// wrapping.
#[test]
fn interval_overflow_is_a_clean_error() {
    let mut t = DataTable::new(
        "iv".to_string(),
        vec![("v".to_string(), DataType::Interval)],
    )
    .unwrap();
    t.append_chunk(vec![vec_of(
        DataType::Interval,
        &[Value::Interval {
            months: 0,
            days: 0,
            micros: i64::MAX,
        }],
    )])
    .unwrap();
    let path = scratch("iv-overflow.arrow");
    let err = ArrowFormat::new().write(&path, &t).unwrap_err().to_string();
    assert!(err.contains("nanosecond interval"), "{err}");
    // The failed write must not leave a half-written file behind as a valid
    // arrow file: the header bytes are already there, so the file is
    // incomplete — clean it up and assert nothing claims it.
    std::fs::remove_file(&path).ok();
}

/// `Interval` is public API of the engine used by the mapping; a compile-time
/// use pins the field names.
#[test]
fn interval_fields_are_the_engines() {
    let iv = Interval {
        months: 3,
        days: 4,
        micros: 5,
    };
    assert_eq!(iv.months + iv.days + iv.micros as i32, 12);
}
